svg.script:
{
  "diagramType": "Integration Architecture",
  "projectName": "Food Delivery System",
  "description": "System integration patterns and protocols",
  "internal_systems": [
    {"id": "is1", "name": "Order System", "position": {"x": 300, "y": 300}},
    {"id": "is2", "name": "Inventory System", "position": {"x": 300, "y": 600}},
    {"id": "is3", "name": "Billing System", "position": {"x": 1600, "y": 300}}
  ],
  "external_partners": [
    {"id": "ep1", "name": "Payment Gateway", "position": {"x": 1600, "y": 600}},
    {"id": "ep2", "name": "SMS Provider", "position": {"x": 1600, "y": 750}}
  ],
  "integration_platform": {
    "id": "ip",
    "name": "ESB / Integration Hub",
    "position": {"x": 960, "y": 500},
    "technologies": ["Apache Kafka", "Spring Integration"]
  },
  "integration_patterns": [
    {"from": "is1", "to": "ip", "pattern": "API", "protocol": "REST/JSON"},
    {"from": "is2", "to": "ip", "pattern": "Event Stream", "protocol": "Kafka"},
    {"from": "is3", "to": "ip", "pattern": "Message Queue", "protocol": "AMQP"}
  ],
  "designTokens": {"lightMode": {"canvas": "#FFFFFF"}, "darkMode": {"canvas": "#0D0D0D"}}
}
